class Solution:
    def smallestAbsent(self, nums: List[int]) -> int:
        s = set(nums)
        c = max(1, int(sum(nums) / len(nums)) + 1)
        while c in s:
            c += 1
        return c

c.cpp:
class Solution {
public:
    int smallestAbsent(vector<int>& nums) {
        double avg = (double)accumulate(nums.begin(), nums.end(), 0LL) / nums.size();
        unordered_set<int> s(nums.begin(), nums.end());
        int c = max(1, (int)floor(avg) + 1);
        while (s.count(c)) c++;
        return c;
    }
};

c.java:
class Solution {
    public int smallestAbsent(int[] nums) {
        double avg = 0;
        for (int x : nums) avg += x;
        avg /= nums.length;
        Set<Integer> s = new HashSet<>();
        for (int x : nums) s.add(x);
        int c = Math.max(1, (int) Math.floor(avg) + 1);
        while (s.contains(c)) c++;
        return c;
    }
}

