var smallestAbsent = function(nums) {
    const avg = nums.reduce((a, b) => a + b, 0) / nums.length;
    const s = new Set(nums);
    let c = Math.max(1, Math.floor(avg) + 1);
    while (s.has(c)) c++;
    return c;
};
